//! JSON output helpers that match `JSON.stringify` exactly.
//!
//! The transit writer produces JSON text, and the corpus is generated by
//! transit-js (which calls `JSON.stringify`). Byte-exact golden tests need two
//! things that Rust's default formatting does not give:
//!
//! * **Number formatting** per `Number::toString` (ECMAScript 262 9.2.5.4), not
//!   Rust's `{}`/`{:?}`: shortest round-trip digits, decimal when `-5 < k <= 21`
//!   where `k` is the position of the decimal point, otherwise exponential with
//!   `e+`/`e-` and 1+ exponent digits (`1e21` -> `1e+21`, `1e-7` -> `1e-7`,
//!   `1e20` -> `100000000000000000000`).
//! * **String escaping** per `JSON.stringify`: the five short escapes
//!   (`\b \t \n \f \r`), `\u00XX` lowercase hex for the other control
//!   characters, and nothing escaped above `0x1F` (non-ASCII passes through as
//!   UTF-8, `/` is not escaped).
//!
//! The reader side just uses `serde_json`.

/// Format `f64` the way `JSON.stringify` would, given the shortest decimal
/// digits `s` (as produced by `format!("{:e}", v)`) and its exponent.
#[must_use]
pub fn fmt_f64(v: f64) -> String {
    if v == 0.0 {
        // Covers both +0 and -0: JS `String(-0)` is "0".
        return "0".to_owned();
    }
    let negative = v < 0.0;
    let magnitude = if negative { -v } else { v };
    let body = fmt_positive(magnitude);
    if negative {
        format!("-{body}")
    } else {
        body
    }
}

fn fmt_positive(v: f64) -> String {
    // Rust's LowerExp gives shortest round-trip digits: "1.2345e2", "1e-7".
    let sci = format!("{v:e}");
    let (mantissa, exp_str) = sci.split_once('e').unwrap_or((sci.as_str(), "0"));
    let exp: i32 = exp_str.parse().unwrap_or(0);

    // Digits are the mantissa without its decimal point; k is the position of
    // the decimal point relative to the first digit.
    let digits: String = mantissa.chars().filter(|c| *c != '.').collect();
    let n = digits.len(); // number of significant digits
    let k = exp + 1;

    if (1..=21).contains(&k) {
        // k is positive and small here; the conversion cannot fail.
        let point = usize::try_from(k).unwrap_or(usize::MAX);
        if point >= n {
            // integer, possibly with trailing zeros: 1e20 -> 1 followed by 20 zeros
            let mut out = digits;
            out.push_str(&"0".repeat(point - n));
            out
        } else {
            // decimal point inside the digits: 123.45 -> k=3, n=5
            let mut out = String::with_capacity(digits.len() + 1);
            out.push_str(&digits[..point]);
            out.push('.');
            out.push_str(&digits[point..]);
            out
        }
    } else if (-5..=0).contains(&k) {
        // 0.000001 style: 0 . (zeros) digits
        let mut out = String::from("0.");
        out.push_str(&"0".repeat(usize::try_from(-k).unwrap_or(0)));
        out.push_str(&digits);
        out
    } else {
        // exponential: d(.ddd)e±E, where E is k-1 with no zero padding
        // (JS prints `1e-7`, not `1e-07`, and `1e+21` with the sign).
        let e = k - 1;
        let mut out = String::new();
        out.push_str(&digits[..1]);
        if n > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        out.push('e');
        if e < 0 {
            out.push('-');
            out.push_str(&(-e).to_string());
        } else {
            out.push('+');
            out.push_str(&e.to_string());
        }
        out
    }
}

/// JSON-escape `s` into `out`, matching `JSON.stringify`.
pub fn escape_json_string(s: &str, out: &mut String) {
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\u{08}' => out.push_str("\\b"),
            '\t' => out.push_str("\\t"),
            '\n' => out.push_str("\\n"),
            '\u{0c}' => out.push_str("\\f"),
            '\r' => out.push_str("\\r"),
            c if (c as u32) < 0x20 => push_unicode_escape(out, c as u32),
            c => out.push(c),
        }
    }
    out.push('"');
}

/// JSON string literal (with quotes).
#[must_use]
pub fn json_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    escape_json_string(s, &mut out);
    out
}

/// Lower-case hex digits, as `JSON.stringify` emits them.
const HEX: [u8; 16] = *b"0123456789abcdef";

fn push_unicode_escape(out: &mut String, value: u32) {
    out.push_str("\\u00");
    out.push(HEX[((value >> 4) & 0xf) as usize] as char);
    out.push(HEX[(value & 0xf) as usize] as char);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    // The literals below are the values under test and their expected text is
    // spelled exactly as JavaScript prints them, so digit separators would
    // obscure the very thing each row asserts.
    #[allow(clippy::unreadable_literal)]
    fn js_number_formatting() {
        let cases: &[(f64, &str)] = &[
            (0.0, "0"),
            (-0.0, "0"),
            (1.0, "1"),
            (100.0, "100"),
            (0.1, "0.1"),
            (1e-6, "0.000001"),
            (1e-7, "1e-7"),
            (1e20, "100000000000000000000"),
            (1e21, "1e+21"),
            (123456.789, "123456.789"),
            (12345678901234567890.0, "12345678901234567000"),
            (1.2345678901234567e29, "1.2345678901234568e+29"),
            (9007199254740991.0, "9007199254740991"),
            (1.0 / 7.0, "0.14285714285714285"),
            (1.5e14, "150000000000000"),
            (3.0, "3"),
            (1.5e-10, "1.5e-10"),
            (0.0000123, "0.0000123"),
            (1e100, "1e+100"),
            (2e-308, "2e-308"),
            (-1.5, "-1.5"),
            (1.7976931348623157e308, "1.7976931348623157e+308"),
        ];
        for (input, expected) in cases {
            assert_eq!(&fmt_f64(*input), expected, "for {input}");
        }
    }

    #[test]
    fn escapes_match_json_stringify() {
        assert_eq!(json_string("a\tb"), "\"a\\tb\"");
        assert_eq!(json_string("a\u{0b}b"), "\"a\\u000bb\"");
        assert_eq!(json_string("a\"b"), "\"a\\\"b\"");
        assert_eq!(json_string("a\\b"), "\"a\\\\b\"");
        assert_eq!(json_string("café"), "\"café\"");
    }
}
